export async function seed(database: D1Database): Promise<void> {
  const stamp = ts();
  const statements: D1PreparedStatement[] = [];

  for (const [key, value] of Object.entries(DEFAULT_SETTINGS)) {
    statements.push(
      database
        // Fill a setting only when it is missing or still empty — never overwrite an admin's value.
        .prepare("INSERT INTO settings (key, value, updated_at) VALUES (?, ?, ?) ON CONFLICT(key) DO UPDATE SET value = excluded.value, updated_at = excluded.updated_at WHERE settings.value = '' OR (settings.key = 'office_address' AND settings.value = 'Kyrenia (Girne), North Cyprus')")
        .bind(key, value, stamp),
    );
  }

  for (const m of TEAM) {
    statements.push(
      database
        .prepare(
          `INSERT OR IGNORE INTO team_members
           (id, slug, name, position, biography, specialties, languages, education, email, phone, is_referral_lead, sort_order, updated_at)
           VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
        )
        .bind(
          crypto.randomUUID(),
          m.slug,
          m.name,
          JSON.stringify(m.position),
          JSON.stringify(m.biography),
          JSON.stringify(m.specialties),
          JSON.stringify(m.languages),
          JSON.stringify(m.education),
          m.email ?? null,
          m.phone ?? null,
          m.referralLead ? 1 : 0,
          m.sort,
          stamp,
        ),
    );
  }

  LAWS.forEach((law, index) => {
    statements.push(
      database
        .prepare(
          `INSERT OR IGNORE INTO laws (id, slug, reference, category, title, status, sort_order, updated_at)
           VALUES (?, ?, ?, ?, ?, 'published', ?, ?)`,
        )
        .bind(
          crypto.randomUUID(),
          law.slug,
          law.reference,
          law.category,
          JSON.stringify(law.title),
          index * 10,
          stamp,
        ),
    );
  });

  await database.batch(statements);
}
